```jsx
import { createContext, useContext, useState, useCallback } from "react";

const ToastContext = createContext(null);

export function ToastProvider({ children }) {
  const [toasts, setToasts] = useState([]);

  const addToast = useCallback((message) => {
    const id = Date.now();
    setToasts((t) => [...t, { id, message }]);
    setTimeout(() => {
      setToasts((t) => t.filter((toast) => toast.id !== id));
    }, 3000);
  }, []);

  return (
    <ToastContext.Provider value={addToast}>
      {children}
      <div style={{ position: "fixed", bottom: 16, right: 16 }}>
        {toasts.map((t) => (
          <div key={t.id} style={{ background: "#333", color: "#fff",
              padding: "8px 12px", marginTop: 8, borderRadius: 4 }}>
            {t.message}
          </div>
        ))}
      </div>
    </ToastContext.Provider>
  );
}

export function useToast() {
  return useContext(ToastContext);
}
```

Wrap your app in `<ToastProvider>`, then call it anywhere:

```jsx
const toast = useToast();
toast("Saved!");
```

A couple of notes: `Date.now()` can collide if you fire two toasts in the same millisecond, so use a counter or `crypto.randomUUID()` in real code. And each `setTimeout` isn't cleared on unmount, which is fine for a demo but worth cleaning up if toasts can outlive the provider.

